cmd:
mkdir -p /var/www/html && printf 'Welcome to the benchmark webserver' > /var/www/html/index.html && printf 'Page not found - Please check your URL' > /var/www/html/404.html && rm -f /etc/nginx/sites-enabled/default && cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark burst=10;

    error_page 404 /404.html;

    location = /404.html {
        internal;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
echo done

cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
